from fastapi import FastAPI
from fastapi.sse import EventSourceResponse, ServerSentEvent
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/sse", response_class=EventSourceResponse)
async def sse_endpoint():
    # Use actual newlines to test validation
    yield ServerSentEvent(
        event="my-event\nbroken",
        id="my-id\nbroken",
        data="some data"
    )

client = TestClient(app)

def test_sse_validation():
    response = client.get("/sse")
    print(f"Status code: {response.status_code}")
    print(f"Content: {response.content}")

    if response.status_code == 200:
        if b"event: my-event" in response.content and b"broken" in response.content:
            print("Bug is present: 200 OK returned for invalid SSE fields")
        else:
            print("Unexpected content")
    else:
        print(f"Validation worked: returned {response.status_code}")

if __name__ == "__main__":
    test_sse_validation()

